set -eu
cat > /etc/nginx/sites-available/antrieb-backend <<'ANTRIEB_NGINX'
server {
    listen 5660 default_server;
    listen [::]:5660 default_server;
    server_name _;

    location = / {
        default_type text/plain;
        return 200 "node1\n";
    }

    location / {
        return 404;
    }
}
ANTRIEB_NGINX
ln -sfn /etc/nginx/sites-available/antrieb-backend /etc/nginx/sites-enabled/antrieb-backend
if [ -L /etc/nginx/sites-enabled/default ]; then unlink /etc/nginx/sites-enabled/default; fi
nginx -t
systemctl enable nginx
systemctl restart nginx

